"use strict";

/* 批次 15 #3 方案 A（2026-09-12）：sharp 0.35.4 条件加载器。
 *
 * 优先加载真模块：@img/sharp-linux-arm64（N-API 绑定，RUNPATH 自带
 * $ORIGIN/../../sharp-libvips-linux-arm64/lib）+ @img/sharp-libvips-linux-arm64
 * （libvips-cpp.so.8.18.6，全部编解码器静态内联）。payload 的 glibc runtime
 * （Node 24.21.0 glibc + glibc 2.44）已设备实测可用（docs/批次15r-原生模块调研报告.md §3.2）。
 *
 * 任何失败 → 回退到本文件下方保留的纯 JS 替身（与历史 overlay 实现逐字一致，
 * 仅整体移入 fallback 分支）：bionic runtime 无法加载 glibc .so、平台不符、
 * 文件缺失、或显式 SHARP_FORCE_SUBSTITUTE=1（真机 A/B 验证开关）时，引擎启动
 * 绝不因 sharp 失败。
 *
 * 探针采用"先 resolve 后 dlopen"：直接 require 上游 dist 会在加载失败时走进
 * 上游 sharp.cjs 的 "Could not load the sharp module" 多行 help（stderr 噪音），
 * 探针路径完全绕开它。探针命中后 dist 内对同一 .node 的 require 命中 require
 * 缓存，不二次 dlopen。
 *
 * 导出面：真模块 = 上游 Sharp 构造器直透（module.exports 原样，不改写）；
 * 回退 = 替身 sharp(data, options?) 函数。dsh-attachment-local 0.1.5-rc.1 用到的
 * sharp(data,{failOn,limitInputPixels}) / .metadata() / .raw().toBuffer() /
 * .rotate() / .toColourspace("srgb") / .resize({width,height,fit,withoutEnlargement})
 * 两侧签名一致（ESM `import sharp from "sharp"` 默认导入两侧均为可调用对象）。
 */

let realSharp = null;
if (process.env.SHARP_FORCE_SUBSTITUTE !== "1") {
  try {
    // 1) 结构探针：绑定包与 libvips 包的产物必须能经 exports 子路径解析（含文件存在性）。
    require.resolve("@img/sharp-linux-arm64/sharp.node");
    require.resolve("@img/sharp-libvips-linux-arm64/binary");
    // 2) dlopen 探针：bionic linker 拒载 glibc .so / glibc 版本不足 / 缺依赖
    //    都在此 throw（dlopen 失败是可捕获的 JS 异常，进程不会崩溃）。
    require("@img/sharp-linux-arm64/sharp.node");
    // 3) 命中后加载上游 dist 入口。
    realSharp = require("../dist/index.cjs");
  } catch (_error) {
    realSharp = null;
  }
}

if (realSharp) {
  module.exports = realSharp;
} else {
  if (process.env.SHARP_DEBUG === "1") {
    console.warn("sharp: native prebuild unavailable, using pure-JS substitute");
  }

  function parsePng(data) {
    if (data.length < 26) return null;
    if (data.readUInt32BE(0) !== 0x89504e47) return null;
    return {
      format: "png",
      width: data.readUInt32BE(16),
      height: data.readUInt32BE(20),
      depth: "uchar",
      space: "srgb",
      hasAlpha: data[25] === 4 || data[25] === 6,
      pages: 1,
    };
  }

  function parseJpeg(data) {
    if (data.length < 4 || data[0] !== 0xff || data[1] !== 0xd8) return null;
    let offset = 2;
    while (offset + 9 < data.length) {
      if (data[offset] !== 0xff) {
        offset += 1;
        continue;
      }
      const marker = data[offset + 1];
      if (marker >= 0xd8 || marker === 0x01 || marker === 0xd0 || marker === 0xd7) {
        offset += 2;
        continue;
      }
      const length = data.readUInt16BE(offset + 2);
      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
        return {
          format: "jpeg",
          width: data.readUInt16BE(offset + 7),
          height: data.readUInt16BE(offset + 5),
          depth: "uchar",
          space: "srgb",
          hasAlpha: false,
          pages: 1,
        };
      }
      if (length < 2) return null;
      offset += 2 + length;
    }
    return null;
  }

  function parseWebp(data) {
    if (
      data.length < 30 ||
      data.toString("ascii", 0, 4) !== "RIFF" ||
      data.toString("ascii", 8, 12) !== "WEBP"
    ) {
      return null;
    }
    const kind = data.toString("ascii", 12, 16);
    let width;
    let height;
    let hasAlpha = false;
    if (kind === "VP8X") {
      const flags = data[20];
      hasAlpha = (flags & 0x10) !== 0;
      width = data.readUIntLE(24, 3) + 1;
      height = data.readUIntLE(27, 3) + 1;
    } else if (kind === "VP8 ") {
      width = data.readUInt16LE(26) & 0x3fff;
      height = data.readUInt16LE(28) & 0x3fff;
    } else if (kind === "VP8L" && data.length >= 25) {
      const bits = data.readUInt32LE(21);
      width = (bits & 0x3fff) + 1;
      height = ((bits >> 14) & 0x3fff) + 1;
    } else {
      return null;
    }
    return {
      format: "webp",
      width,
      height,
      depth: "uchar",
      space: "srgb",
      hasAlpha,
      pages: 1,
    };
  }

  function parseGif(data) {
    if (data.length < 10 || data.toString("ascii", 0, 3) !== "GIF") return null;
    return {
      format: "gif",
      width: data.readUInt16LE(6),
      height: data.readUInt16LE(8),
      depth: "uchar",
      space: "srgb",
      hasAlpha: true,
      pages: 1,
    };
  }

  function detectMetadata(input) {
    const data = Buffer.from(input);
    return parsePng(data) || parseJpeg(data) || parseWebp(data) || parseGif(data);
  }

  class ImagePipeline {
    constructor(data) {
      this._data = Buffer.from(data);
    }

    clone() {
      return new ImagePipeline(this._data);
    }

    rotate() {
      return this;
    }

    toColourspace() {
      return this;
    }

    resize() {
      return this;
    }

    raw() {
      return this;
    }

    jpeg() {
      return this;
    }

    webp() {
      return this;
    }

    png() {
      return this;
    }

    async metadata() {
      const metadata = detectMetadata(this._data);
      if (metadata === null) throw new Error("unsupported image format");
      return metadata;
    }

    async toBuffer(options) {
      const metadata = await this.metadata();
      const payload = new Uint8Array(this._data);
      if (options && options.resolveWithObject) {
        return {
          data: payload,
          info: {
            width: metadata.width,
            height: metadata.height,
            channels: metadata.hasAlpha ? 4 : 3,
            format: metadata.format,
          },
        };
      }
      return payload;
    }
  }

  function sharp(data) {
    return new ImagePipeline(data);
  }

  sharp.cache = () => {};
  sharp.concurrency = () => 1;

  module.exports = sharp;
  module.exports.default = sharp;
}
